/**
 * Post-process the Xcode project generated by safari-web-extension-converter.
 *
 * The converter derives the host app's PRODUCT_BUNDLE_IDENTIFIER from --app-name
 * (e.g. "Hermes Browser" -> io.github.abundantbeing.Hermes-Browser) while the
 * extension target gets --bundle-identifier + ".Extension". Xcode then refuses
 * to embed the appex because its identifier is not prefixed by the host app's.
 * This rewrites the app target's identifier to the extension prefix.
 */
import fs from 'node:fs';
import path from 'node:path';

const projectFile = process.argv[2]
  || path.join(process.cwd(), 'safari', 'Hermes Browser', 'Hermes Browser.xcodeproj', 'project.pbxproj');

const source = fs.readFileSync(projectFile, 'utf8');
const identifiers = [...source.matchAll(/PRODUCT_BUNDLE_IDENTIFIER = "([^"]+)";/g)]
  .map((match) => match[1]);
const extensionId = identifiers.find((id) => id.endsWith('.Extension'));
if (!extensionId) {
  console.error(`No .Extension bundle identifier found in ${projectFile}`);
  process.exit(1);
}
const hostId = extensionId.slice(0, -'.Extension'.length);
const patched = source.replaceAll(
  /PRODUCT_BUNDLE_IDENTIFIER = "([^"]+)";/g,
  (line, id) => (id === extensionId || id === hostId ? line : `PRODUCT_BUNDLE_IDENTIFIER = "${hostId}";`),
);
const changed = patched !== source;
fs.writeFileSync(projectFile, patched);
console.log(changed
  ? `Patched host bundle identifier to ${hostId} in ${projectFile}`
  : `Host bundle identifier already ${hostId}`);
